export async function capacityCheckRamMB(ramMB: number): Promise<{ ok: boolean; reason?: string }> {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) {
    // No Node rows configured — fall back to the original flat, env-configured
    // single-host ceiling (matches pre-multi-node behavior/tests).
    const snap = await capacitySnapshot();
    if (ramProjectionExceedsCeiling(snap.committedRamMB, snap.ceilingRamMB, ramMB)) {
      return {
