          "Please try a smaller plan or contact support.",
      };
    }
    return { ok: true };
  }

  const primary = nodes.find((n) => n.isPrimary) ?? nodes[0];
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const servers = await db.server.findMany({
        where: {
          status: { not: "DELETING" },
          OR: n.id === primary.id ? [{ nodeId: n.id }, { nodeId: null }] : [{ nodeId: n.id }],
        },
        select: { plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
